"""Aptitude pack: 60 quant, 50 logical, 40 verbal. Q(question, answer, [3 wrong], why, check) where check() recomputes the
answer in Python and must equal `answer` (as a string). Verbal items have no check; they were written and reviewed by hand."""
from fractions import Fraction as F
from math import comb, factorial, perm
import datetime, itertools
SECTIONS = {}
def Q(q, a, wrong, why, check=None): return dict(q=q, a=a, wrong=wrong, why=why, check=check)
def fr(x): x = F(x).limit_denominator(10000); return str(x.numerator) if x.denominator == 1 else f"{x.numerator}/{x.denominator}"
def num(x): x = float(x); return str(int(x)) if x == int(x) else f"{x:g}"
def wd(y, m, d): return datetime.date(y, m, d).strftime("%A")
def shift(word, k): return "".join(chr((ord(c) - 65 + k) % 26 + 65) for c in word)
def factors(n): return sum(1 for i in range(1, n + 1) if n % i == 0)
def tz(n):
    z, p = 0, 5
    while p <= n: z += n // p; p *= 5
    return z

